import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Set;
import java.util.HashSet;

@Service
public class CourseServiceImpl implements CourseService {

    @Autowired
    private CourseMapper courseMapper;

    @Autowired
    private CourseSelectionMapper courseSelectionMapper;

    @Autowired
    private UserMapper userMapper;

    @Override
    public List<Course> getAllCourses(String username) {
        // 1. 获取所有课程
        List<Course> courses = courseMapper.getAllCourses(); // 假设你原有的方法叫 getAllCourses

        // 2. 如果用户已登录，查出他选过的课程ID
        if (username != null && !username.isEmpty()) {
            User user = userMapper.findByUsername(username);
            if (user != null) {
                // 查已选课程ID列表
                List<Long> selectedCourseIds = courseSelectionMapper.selectCourseIdsByStudentId(user.getId());
                Set<Long> selectedSet = new HashSet<>(selectedCourseIds);

                // 3. 遍历课程，打上 isSelected 标记
                for (Course course : courses) {
                    course.setIsSelected(selectedSet.contains(course.getId()));
                }
            }
        }
        return courses;
    }
}
