            console.error('请求失败:', url, res.status, text);
            throw new Error('服务器错误 ' + res.status);
        }
        return res.json();
    }

    async function loadScores() {
        try {
            const scores = await request('/score/my');
            const emptyTip = document.getElementById('emptyTip');
            const tableWrap = document.getElementById('tableWrap');
            const summary = document.getElementById('summary');

            if (!scores || scores.length === 0) {
                emptyTip.style.display = 'block';
                tableWrap.style.display = 'none';
                summary.style.display = 'none';
                return;
            }

            emptyTip.style.display = 'none';
            tableWrap.style.display = 'block';
            summary.style.display = 'flex';

            // ===== 统计 =====
            let total = 0;
            let maxScore = 0;
            let totalCredit = 0;
            scores.forEach(s => {
                const sc = parseFloat(s.score);
                total += sc;
                if (sc > maxScore) maxScore = sc;
                // 及格（>=60）才算获得学分
                if (sc >= 60) totalCredit += (s.credit || 0);
            });
            const avg = (total / scores.length).toFixed(1);
            document.getElementById('courseCount').innerHTML = scores.length + '<small>门</small>';
            document.getElementById('avgScore').innerHTML = avg + '<small>分</small>';
            document.getElementById('maxScore').innerHTML = maxScore + '<small>分</small>';
            document.getElementById('totalCredit').innerHTML = totalCredit + '<small>分</small>';

            // ===== 表格 =====
            const tbody = document.getElementById('scoreTable');
            tbody.innerHTML = '';
            scores.forEach(s => {
                const sc = parseFloat(s.score);
                const pass = sc >= 60;
                tbody.innerHTML += `
                    <tr>
                        <td>${s.courseName}</td>
                        <td>${s.teacherName || '-'}</td>
                        <td>${s.credit}</td>
                        <td class="score-num ${pass ? 'score-pass' : 'score-fail'}">${sc}</td>
                        <td>
                            <span class="tag ${pass ? 'tag-pass' : 'tag-fail'}">
                                ${pass ? '及格' : '不及格'}
                            </span>
                        </td>
                    </tr>
                `;
            });
        } catch (e) {
            console.error('加载成绩失败:', e);
        }
    }

    function logout() {
        localStorage.clear();
        window.location.href = '/login.html';
    }

    loadScores();
</script>
</body>
</html>
```

