<script>
    const token = localStorage.getItem('token');
    const role = (localStorage.getItem('role') || '').replace('ROLE_', '');

    // ✅ 角色校验
    if (!token) {
        window.location.href = '/login.html';
    } else if (role !== 'TEACHER') {
        alert('无权访问教师端页面');
        localStorage.clear();
        window.location.href = '/login.html';
    }

    async function request(url, options = {}) {
        const res = await fetch(url, {
            ...options,
            headers: {
                'Authorization': 'Bearer ' + token,
                ...(options.headers || {})
            }
        });
        if (res.status === 401 || res.status === 403) {
            alert('登录已过期，请重新登录');
            localStorage.clear();
            window.location.href = '/login.html';
            throw new Error('未授权');
        }
        if (!res.ok) {
            const text = await res.text();
            console.error('请求失败:', url, res.status, text);
            throw new Error('服务器错误 ' + res.status);
        }
        return res.json();
    }

    async function loadCourses() {
        try {
            const courses = await request('/teacher/courses');
            const list = document.getElementById('courseList');
            const emptyTip = document.getElementById('emptyTip');
            const summary = document.getElementById('summary');

            if (!courses || courses.length === 0) {
                emptyTip.style.display = 'block';
                summary.style.display = 'none';
                list.innerHTML = '';
                return;
            }

            emptyTip.style.display = 'none';
            summary.style.display = 'flex';

            // ===== 统计 =====
            let totalCredit = 0;
            let totalStudents = 0;
            courses.forEach(c => {
                totalCredit += (c.credit || 0);
                totalStudents += (c.selectedCount || 0);
            });
            document.getElementById('courseCount').innerHTML = courses.length + '<small>门</small>';
            document.getElementById('totalCredit').innerHTML = totalCredit + '<small>分</small>';
            document.getElementById('totalStudents').innerHTML = totalStudents + '<small>人</small>';

            // ===== 渲染课程卡片 =====
            list.innerHTML = '';
            courses.forEach(c => {
                const selected = c.selectedCount || 0;
                const capacity = c.capacity || 1;
                const percent = Math.min(100, Math.round(selected / capacity * 100));
                const isFull = selected >= capacity;

                list.innerHTML += `
                    <div class="course-card">
                        <div class="course-name">
                            ${c.courseName}
                            ${isFull ? '<span style="font-size:12px;color:#ff4d4f;">（已满）</span>' : ''}
                        </div>
                        <div class="info-row">
                            <span>课程 ID</span>
                            <span class="val">#${c.id}</span>
                        </div>
                        <div class="info-row">
                            <span>学分</span>
                            <span class="val">${c.credit} 分</span>
                        </div>
                        <div class="info-row">
                            <span>选课人数</span>
                            <span class="val">${selected} / ${capacity} 人</span>
                        </div>
                        <div class="progress-bar">
                            <div class="progress-inner" style="width: ${percent}%;
                                ${isFull ? 'background:#ff7875;' : ''}"></div>
                        </div>
                        <div class="actions">
                            <button class="btn-view" onclick="viewStudents(${c.id}, '${c.courseName}')">
                                👥 查看学生
                            </button>
                            <button class="btn-grade" onclick="inputGrade(${c.id}, '${c.courseName}')">
                                ✏️ 录入成绩
                            </button>
                        </div>
                    </div>
                `;
            });

        } catch (e) {
            console.error('加载课程失败:', e);
        }
    }

    function viewStudents(courseId, courseName) {
