<script>
    const token = localStorage.getItem('token');
    const role = (localStorage.getItem('role') || '').replace('ROLE_', '');

    if (!token) window.location.href = '/login.html';
    else if (role !== 'TEACHER') { alert('无权访问'); localStorage.clear(); window.location.href = '/login.html'; }

    const params = new URLSearchParams(window.location.search);
    const courseId = params.get('courseId');
    const courseName = params.get('courseName');

    if (!courseId) {
        alert('缺少课程参数');
        window.location.href = '/teacher-course.html';
    }
    document.getElementById('courseName').innerText = courseName || '未知课程';

    async function request(url, options = {}) {
        const res = await fetch(url, {
            ...options,
            headers: { 'Authorization': 'Bearer ' + token, ...(options.headers || {}) }
        });
        if (res.status === 401 || res.status === 403) {
            alert('登录已过期'); localStorage.clear(); window.location.href = '/login.html';
            throw new Error('未授权');
        }
        if (!res.ok) throw new Error('服务器错误 ' + res.status);
        return res.json();
    }

    async function loadStudents() {
        try {
            const students = await request('/teacher/students?courseId=' + courseId);
            const summary = document.getElementById('summary');
            const tableWrap = document.getElementById('tableWrap');
            const emptyTip = document.getElementById('emptyTip');

            summary.style.display = 'flex';

            if (!students || students.length === 0) {
                emptyTip.style.display = 'block';
                tableWrap.style.display = 'none';
                return;
            }

            emptyTip.style.display = 'none';
            tableWrap.style.display = 'block';

            let graded = 0;
            const tbody = document.getElementById('studentTable');
            tbody.innerHTML = '';

            students.forEach(s => {
                const hasScore = s.score !== null && s.score !== undefined;
                if (hasScore) graded++;

                const scoreVal = hasScore ? parseFloat(s.score) : '';
                const inputId = `input-${s.studentId}`;

                tbody.innerHTML += `
