                        <td>${s.studentUsername}</td>
                        <td>${s.studentName}</td>
                        <td>
                            <input type="number" class="score-input" 
                                   id="${inputId}" 
                                   value="${scoreVal}" 
                                   min="0" max="100" step="0.1" placeholder="未录入">
                        </td>
                        <td>
                            <button class="btn-save" onclick="saveScore(${s.studentId}, '${inputId}', this)">保存</button>
                        </td>
                    </tr>
                `;
            });

            document.getElementById('studentCount').innerHTML = students.length + '<small>人</small>';
            document.getElementById('gradedCount').innerHTML = graded + '<small>人</small>';

        } catch (e) {
            console.error(e);
            alert('加载名单失败：' + e.message);
        }
    }

    async function saveScore(studentId, inputId, btnObj) {
        const input = document.getElementById(inputId);
        const val = input.value.trim();
        if (val === '') {
            alert('请输入成绩');
            return;
        }

        const scoreNum = parseFloat(val);
        if (isNaN(scoreNum) || scoreNum < 0 || scoreNum > 100) {
            alert('成绩必须在 0-100 之间');
            return;
        }

        btnObj.disabled = true;
        btnObj.innerText = '保存中...';

        try {
            const res = await request('/teacher/grade', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    studentId: studentId,
                    courseId: courseId,
                    score: scoreNum
                })
            });

            if (res.success) {
                btnObj.innerText = '已保存';
                btnObj.style.background = '#b7eb8f';
                // 重新计算已录入人数
                loadStudents(); 
            } else {
                alert(res.message);
                btnObj.disabled = false;
                btnObj.innerText = '保存';
            }
        } catch (e) {
            alert('保存失败：' + e.message);
            btnObj.disabled = false;
            btnObj.innerText = '保存';
        }
    }

    function logout() {
        localStorage.clear();
        window.location.href = '/login.html';
    }

    loadStudents();
</script>
