### 🚀 其他页面（如选课、成绩）如何配合？

因为现在它们被装进了 `iframe` 中，**它们自己的头部和背景会显得多余**。

你要做的是：在 `student-course.html`、`student-score.html` 等子页面中，**把最上面的 `<div class="header">...</div>` 删掉，把 `<body>` 的 padding 改成 `padding: 30px;`**，这样它们加载到右侧时，就像是从一个精美的系统里无缝切换出来的。

你可以先试一下现在的效果：点击左侧菜单，右侧会瞬间切换，而且浏览器上的整个页面绝对不会闪烁或刷新。如果你确认效果完美，我们就按这个节奏把教师端也改成这种！💪

从你发来的代码看，确实**还没有加上允许 iframe 的配置**。因为 Spring Security 默认开启了 `X-Frame-Options: DENY`，这个安全策略会直接阻止浏览器在 `iframe` 里加载网页，从而报出“拒绝连接”。

请把你现在的 `SecurityConfig.java` **完整替换成下面这份代码**（注意看 `// ✅ 新增` 那一行）：

### 📄 完整的 `SecurityConfig.java`

```java
package com.students.jwsystem_public.config;

import com.students.jwsystem_public.filter.JwtAuthenticationFilter;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import java.util.List;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Autowired
    private JwtAuthenticationFilter jwtAuthenticationFilter;

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .cors(Customizer.withDefaults())
                .csrf(AbstractHttpConfigurer::disable)
                // ✅ 新增：允许 iframe 嵌套，解决拒绝连接问题
                .headers(headers -> headers.frameOptions(frame -> frame.disable()))
                .formLogin(AbstractHttpConfigurer::disable)
                .httpBasic(AbstractHttpConfigurer::disable)
                .authorizeHttpRequests(auth -> auth
                        // 放行验证码接口
                        .requestMatchers("/captcha").permitAll()
                        // 放行登录相关接口
                        .requestMatchers("/auth/**").permitAll()
                        // 放行静态资源
                        .requestMatchers(
                                "/login.html",
                                "/index.html",
                                "/favicon.ico",
                                "/css/**",
                                "/js/**",
                                "/images/**",
                                "/*.html"
                        ).permitAll()
                        // 其他请求需要认证
                        .anyRequest().authenticated()
                )
                .sessionManagement(session -> session
                        .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
                )
                // 把 JWT 过滤器加到用户名密码认证过滤器之前
                .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }

    /**
     * CORS 配置源
     */
    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration config = new CorsConfiguration();
        config.setAllowedOriginPatterns(List.of("*"));
        config.setAllowedMethods(List.of("GET", "POST", "PUT", "DELETE", "OPTIONS"));
        config.setAllowedHeaders(List.of("*"));
        config.setAllowCredentials(true);

        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/**", config);
        return source;
    }

    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {
        return config.getAuthenticationManager();
    }
}
```

