import com.students.jwsystem_public.service.CourseScheduleService;
import com.students.jwsystem_public.service.CourseSelectionService;
import com.students.jwsystem_public.service.CourseService;
import com.students.jwsystem_public.service.ScoreService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/teacher")
public class TeacherController {

    @Autowired private CourseService courseService;
    @Autowired private CourseScheduleService courseScheduleService;
    @Autowired private CourseSelectionService courseSelectionService;
    @Autowired private ScoreService scoreService;

    @Autowired private UserMapper userMapper;
    @Autowired private ScoreMapper scoreMapper;

    @GetMapping("/courses")
    public List<Course> getMyCourses() {
        String username = SecurityContextHolder.getContext().getAuthentication().getName();
        return courseService.getTeacherCourses(username);
    }

    @GetMapping("/schedule")
    public List<CourseSchedule> getSchedule() {
        String username = SecurityContextHolder.getContext().getAuthentication().getName();
        return courseScheduleService.getTeacherSchedule(username);
    }

    // 获取某门课的学生名单（含成绩）
    @GetMapping("/students")
    public List<CourseSelection> getStudents(@RequestParam("courseId") Long courseId) {
        return courseSelectionService.getStudentsByCourseId(courseId);
    }

    // 获取该教师名下的全部学生
    @GetMapping("/all-students")
    public List<CourseSelection> getAllStudents() {
        String username = SecurityContextHolder.getContext().getAuthentication().getName();
        return courseSelectionService.getAllStudentsByTeacher(username);
    }

    @PostMapping("/grade")
    public Map<String, Object> saveGrade(@RequestBody Map<String, Object> params) {
        Map<String, Object> result = new HashMap<>();
        try {
            Long studentId = Long.valueOf(params.get("studentId").toString());
            Long courseId = Long.valueOf(params.get("courseId").toString());
            Double scoreValue = Double.valueOf(params.get("score").toString());

            boolean success = scoreService.saveOrUpdateScore(studentId, courseId, scoreValue);
            result.put("success", success);
            result.put("message", success ? "成绩保存成功" : "保存失败");
        } catch (Exception e) {
            result.put("success", false);
            result.put("message", e.getMessage());
        }
        return result;
    }

    // ==========================================
    // ✅ 新增：删除学生（级联删除成绩、选课记录、账号）
    // ==========================================
    @PostMapping("/delete-student/{id}")
    @Transactional
    public Map<String, Object> deleteStudent(@PathVariable Long id) {
        Map<String, Object> result = new HashMap<>();
        try {
            scoreMapper.deleteByStudentId(id);
            courseSelectionService.deleteByStudentId(id); 
            userMapper.deleteById(id);
            result.put("success", true);
            result.put("message", "学生账号及所有记录已彻底删除");
        } catch (Exception e) {
            result.put("success", false);
            result.put("message", "删除失败: " + e.getMessage());
        }
        return result;
    }

    // ==========================================
    // ✅ 新增：将已有学生加入到指定课程
    // ==========================================
    @PostMapping("/add-student-to-course")
    @Transactional
    public Map<String, Object> addStudentToCourse(@RequestBody Map<String, String> params) {
        Map<String, Object> result = new HashMap<>();
        try {
            String studentUsername = params.get("studentUsername");
            Long courseId = Long.valueOf(params.get("courseId"));
            String teacherUsername = SecurityContextHolder.getContext().getAuthentication().getName();

            // 1. 查学生存不存在
            User student = userMapper.findByUsername(studentUsername);
            if (student == null || !"STUDENT".equals(student.getRole())) {
                throw new RuntimeException("未找到该学号对应的学生");
            }

            // 2. 查课程存不存在，以及是不是这个老师的课
            Course course = courseService.getCourseById(courseId);
            User teacher = userMapper.findByUsername(teacherUsername);
            if (course == null || !course.getTeacherId().equals(teacher.getId())) {
                throw new RuntimeException("课程不存在或您无权操作该课程");
            }

            // 3. 检查学生是不是已经在这门课里了
            boolean isAlreadySelected = courseSelectionService.getStudentsByCourseId(courseId)
                    .stream().anyMatch(s -> s.getStudentId().equals(student.getId()));
            if (isAlreadySelected) {
                throw new RuntimeException("该学生已经在您的这门课程中，无需重复添加");
            }

            // 4. 检查课是否满了
            if (course.getSelectedCount() >= course.getCapacity()) {
                throw new RuntimeException("该课程人数已满，无法添加");
            }

            // 5. 帮学生强制选课（插入选课记录 + 课程人数+1）
            courseSelectionService.forceSelectCourse(student.getId(), courseId);

            result.put("success", true);
            result.put("message", "添加成功！已将【" + student.getRealName() + "】加入课程");
        } catch (Exception e) {
            result.put("success", false);
            result.put("message", e.getMessage());
        }
        return result;
    }
}
