<script>
    const API = 'http://localhost:8080';
    let currentKey = ''; // 图形验证码 key
    let countdownTimer = null;

    // --- 视图切换 ---
    function switchPanel(panelId) {
        document.querySelectorAll('.form-panel').forEach(p => p.classList.remove('active'));
        document.getElementById(panelId).classList.add('active');
        document.getElementById('message').innerText = '';
    }

    // --- 图形验证码加载 ---
    async function loadCaptcha() {
        try {
            const res = await fetch(`${API}/captcha`);
            const data = await res.json();
            currentKey = data.key;
            document.getElementById('captchaImg').src = data.image;
        } catch (e) { console.error('加载验证码失败', e); }
    }
    document.getElementById('captchaImg').onclick = loadCaptcha;

    // --- 账号密码登录 ---
    async function doLogin() {
        const username = document.getElementById('username').value.trim();
        const password = document.getElementById('password').value;
        const captcha = document.getElementById('captcha').value.trim();
        const msg = document.getElementById('message');

        if (!username || !password || !captcha) {
            return showMsg('请填写完整信息', 'error');
        }

        try {
            const res = await fetch(`${API}/auth/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password, captcha, key: currentKey })
            });
            const data = await res.json();

            if (data.success) {
                handleLoginSuccess(data);
            } else {
                showMsg(data.message || '登录失败', 'error');
                loadCaptcha();
                document.getElementById('captcha').value = '';
            }
        } catch (e) { showMsg('请求失败：' + e.message, 'error'); }
    }

    // --- 发送邮箱验证码（通用） ---
    async function sendEmailCode(type) {
        const emailInput = type === 'login' ? document.getElementById('emailLoginInput') : document.getElementById('emailResetInput');
        const btn = type === 'login' ? document.getElementById('btnSendLoginCode') : document.getElementById('btnSendResetCode');
        const email = emailInput.value.trim();

        if (!email) return showMsg('请先输入邮箱', 'error');

        btn.disabled = true;
        btn.innerText = '发送中...';

        try {
            // 这里调用后端的发送邮件接口
            const url = type === 'login' ? '/auth/sendLoginCode' : '/auth/sendResetCode';
            const res = await fetch(`${API}${url}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email })
            });
            const data = await res.json();

            if (data.success) {
                showMsg('验证码已发送至您的邮箱，请查收', 'success');
                startCountdown(btn);
            } else {
                showMsg(data.message || '发送失败', 'error');
                btn.disabled = false;
                btn.innerText = '获取验证码';
            }
        } catch (e) {
            showMsg('请求失败', 'error');
            btn.disabled = false;
            btn.innerText = '获取验证码';
        }
    }

    // 倒计时
    function startCountdown(btn) {
        let seconds = 60;
        btn.innerText = `${seconds}s 后重发`;
        countdownTimer = setInterval(() => {
            seconds--;
            if (seconds <= 0) {
                clearInterval(countdownTimer);
                btn.disabled = false;
                btn.innerText = '获取验证码';
            } else {
                btn.innerText = `${seconds}s 后重发`;
            }
        }, 1000);
    }

    // --- 邮箱登录 ---
    async function doEmailLogin() {
        const email = document.getElementById('emailLoginInput').value.trim();
        const code = document.getElementById('emailLoginCode').value.trim();

        if (!email || !code) return showMsg('请填写邮箱和验证码', 'error');

        try {
            const res = await fetch(`${API}/auth/loginByEmail`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, code })
            });
            const data = await res.json();

            if (data.success) {
                handleLoginSuccess(data);
            } else {
                showMsg(data.message || '登录失败', 'error');
            }
        } catch (e) { showMsg('请求失败', 'error'); }
    }

    // --- 重置密码 ---
    async function doResetPassword() {
        const email = document.getElementById('emailResetInput').value.trim();
        const code = document.getElementById('emailResetCode').value.trim();
        const newPassword = document.getElementById('newPassword').value;

        if (!email || !code || !newPassword) return showMsg('请填写完整信息', 'error');

        try {
            const res = await fetch(`${API}/auth/resetPassword`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, code, newPassword })
            });
            const data = await res.json();

            if (data.success) {
                showMsg('密码重置成功，请重新登录', 'success');
                setTimeout(() => switchPanel('panelAccount'), 1500);
            } else {
                showMsg(data.message || '重置失败', 'error');
            }
        } catch (e) { showMsg('请求失败', 'error'); }
    }

    // --- 统一处理登录成功 ---
    function handleLoginSuccess(data) {
        localStorage.setItem('token', data.token);
        localStorage.setItem('role', data.role);
        localStorage.setItem('username', data.username);
        showMsg('登录成功，正在跳转...', 'success');

        const role = (data.role || '').replace('ROLE_', '');
        setTimeout(() => {
            if (role === 'STUDENT') window.location.href = '/student.html';
            else if (role === 'TEACHER') window.location.href = '/teacher.html';
            else if (role === 'ADMIN') window.location.href = '/admin.html';
            else showMsg('未知角色：' + data.role, 'error');
        }, 800);
    }

    function showMsg(text, type) {
        const msg = document.getElementById('message');
        msg.className = 'message ' + type;
        msg.innerText = text;
    }

    document.getElementById('password').onkeydown = (e) => { if (e.key === 'Enter') doLogin(); };

    // 初始化
    loadCaptcha();
</script>
</body>
</html>
