```html
<script>
    const token = localStorage.getItem('token');
    if (!token) { window.top.location.href = '/login.html'; }

    fetch('/admin/stats', { 
        headers: { 'Authorization': 'Bearer ' + token } 
    })
    .then(res => res.json())
    .then(data => {
        // ✅ 修复：安全地处理 0 的情况，防止出现死循环负数
        animateValue("studentCount", data.studentCount || 0, "人");
        animateValue("teacherCount", data.teacherCount || 0, "人");
        animateValue("courseCount", data.courseCount || 0, "门");
    })
    .catch(err => console.error(err));

    // ✅ 重写的数字滚动动画，绝对稳定
    function animateValue(id, end, unit) {
        const obj = document.getElementById(id);

        // 如果数据是 0 或者无效，直接显示，不执行动画
        if (!end || end <= 0) {
            obj.innerHTML = `0<small>${unit}</small>`;
            return;
        }

        let start = 0;
        let duration = 1000; // 动画持续 1 秒
        let startTime = null;

        function step(timestamp) {
            if (!startTime) startTime = timestamp;
            const progress = Math.min((timestamp - startTime) / duration, 1);
            // 计算当前值（缓动函数）
            const current = Math.floor(progress * (end - start) + start);
            obj.innerHTML = current + `<small>${unit}</small>`;

            if (progress < 1) {
                window.requestAnimationFrame(step);
            } else {
                // 动画结束，确保最终数字是准确的
                obj.innerHTML = end + `<small>${unit}</small>`;
            }
        }

        window.requestAnimationFrame(step);
    }
</script>
```

### 🔍 为什么会这样？
之前的代码里有这一句：`const increment = end > start ? 1 : -1;`。
当你的数据库里学生总数是 `0` 时，`end` 是 `0`，`start` 也是 `0`。于是 `end > start` 不成立，`increment` 就被赋予了 `-1`。然后定时器开始跑，数字就变成了 `0, -1, -2, -3...` 无限死循环减下去了。

