```java
package com.students.jwsystem_public.controller;

import com.students.jwsystem_public.entity.User;
import com.students.jwsystem_public.mapper.CourseMapper;
import com.students.jwsystem_public.mapper.UserMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/admin")
public class AdminController {

    @Autowired private UserMapper userMapper;
    @Autowired private CourseMapper courseMapper;

    @GetMapping("/stats")
    public Map<String, Object> getStats() {
        Map<String, Object> result = new HashMap<>();
        result.put("studentCount", userMapper.countByRole("STUDENT"));
        result.put("teacherCount", userMapper.countByRole("TEACHER"));
        result.put("courseCount", courseMapper.countAllCourses());
        return result;
    }

    // ✅ 新增：获取所有用户列表
    @GetMapping("/users")
    public List<User> getAllUsers() {
        return userMapper.findAll();
    }

    // ✅ 新增：重置密码（默认重置为 123456）
    @PostMapping("/reset-password/{id}")
    public Map<String, Object> resetPassword(@PathVariable Long id) {
        Map<String, Object> result = new HashMap<>();
        try {
            userMapper.resetPassword(id, "123456");
            result.put("success", true);
            result.put("message", "密码已成功重置为 123456");
        } catch (Exception e) {
            result.put("success", false);
            result.put("message", "重置失败: " + e.getMessage());
        }
        return result;
    }
}
```

