    function closeModal() { document.getElementById('addModal').style.display = 'none'; }

    async function submitData(type, parentId) {
        const name = document.getElementById('m-name').value.trim();
        if(!name) return alert('请填写名称');

        let url = '', body = {};
        if(type === 'dept') { url = '/admin/add-dept'; body = { deptName: name }; }
        if(type === 'major') { url = '/admin/add-major'; body = { majorName: name, deptId: parentId }; }
        if(type === 'class') { url = '/admin/add-class'; body = { className: name, majorId: parentId }; }

        const data = await request(url, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body) });
        alert(data.message);
        if(data.success) {
            closeModal();
            if(type === 'dept') loadDepts();
            if(type === 'major') loadMajors();
            if(type === 'class') loadClasses();
        }
    }

    loadDepts();
</script>
