### 📌 第 0 步：执行数据库 SQL（最重要）
先去 MySQL 里运行这段 SQL，把字典表建好，并且把 `user` 和 `course` 表的文本字段换成外键 ID：

```sql
-- 1. 建基础字典表
CREATE TABLE IF NOT EXISTS department (id BIGINT AUTO_INCREMENT PRIMARY KEY, dept_name VARCHAR(50) NOT NULL);
CREATE TABLE IF NOT EXISTS major (id BIGINT AUTO_INCREMENT PRIMARY KEY, major_name VARCHAR(50) NOT NULL, dept_id BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sys_class (id BIGINT AUTO_INCREMENT PRIMARY KEY, class_name VARCHAR(50) NOT NULL, major_id BIGINT NOT NULL);

-- 2. 插入初始数据
INSERT INTO department (id, dept_name) VALUES (1, '信息工程学院'), (2, '计算机科学学院');
INSERT INTO major (id, major_name, dept_id) VALUES (1, '软件工程', 1), (2, '计算机科学与技术', 2);
INSERT INTO sys_class (id, class_name, major_id) VALUES (1, '软件工程2101班', 1), (2, '计算机科学2102班', 2);

-- 3. 改造 user 表
ALTER TABLE `user` ADD COLUMN `dept_id` BIGINT DEFAULT NULL;
ALTER TABLE `user` ADD COLUMN `class_id` BIGINT DEFAULT NULL;
UPDATE `user` SET class_id = 1, dept_id = 1 WHERE class_name = '软件工程2101班';
UPDATE `user` SET class_id = 2, dept_id = 2 WHERE class_name = '计算机科学2102班';
UPDATE `user` SET dept_id = 1 WHERE role = 'TEACHER';
ALTER TABLE `user` DROP COLUMN `department`;
ALTER TABLE `user` DROP COLUMN `class_name`;

-- 4. 改造 course 表
ALTER TABLE `course` ADD COLUMN `dept_id` BIGINT DEFAULT NULL;
UPDATE `course` SET `dept_id` = 1;
```

