### 📌 第 2 步：新建基础数据 Mapper

**1. 新建 `BasicDataMapper.java`**
```java
package com.students.jwsystem_public.mapper;

import com.students.jwsystem_public.entity.Department;
import com.students.jwsystem_public.entity.Major;
import com.students.jwsystem_public.entity.SysClass;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;

import java.util.List;

@Mapper
public interface BasicDataMapper {
    List<Department> findAllDepts();
    int insertDept(@Param("deptName") String deptName);

    List<Major> findMajorsByDeptId(@Param("deptId") Long deptId);
    int insertMajor(@Param("majorName") String majorName, @Param("deptId") Long deptId);

    List<SysClass> findClassesByMajorId(@Param("majorId") Long majorId);
    int insertClass(@Param("className") String className, @Param("majorId") Long majorId);
}
```

**2. 新建 `BasicDataMapper.xml`**
```xml
<?xml version="1.0" encoding="UTF-8" ?>
<!DOCTYPE mapper PUBLIC "-//mybatis.org//DTD Mapper 3.0//EN" "http://mybatis.org/dtd/mybatis-3-mapper.dtd" >
<mapper namespace="com.students.jwsystem_public.mapper.BasicDataMapper">
    <select id="findAllDepts" resultType="com.students.jwsystem_public.entity.Department">
        select id, dept_name as deptName from department order by id
    </select>
    <insert id="insertDept">
        insert into department (dept_name) values (#{deptName})
    </insert>

    <select id="findMajorsByDeptId" resultType="com.students.jwsystem_public.entity.Major">
        select id, major_name as majorName, dept_id as deptId from major where dept_id = #{deptId}
    </select>
    <insert id="insertMajor">
        insert into major (major_name, dept_id) values (#{majorName}, #{deptId})
    </insert>

    <select id="findClassesByMajorId" resultType="com.students.jwsystem_public.entity.SysClass">
        select id, class_name as className, major_id as majorId from sys_class where major_id = #{majorId}
    </select>
    <insert id="insertClass">
        insert into sys_class (class_name, major_id) values (#{className}, #{majorId})
    </insert>
</mapper>
