<mapper namespace="com.students.jwsystem_public.mapper.UserMapper">

    <sql id="selectUserSql">
        select u.id, u.username, u.password, u.real_name as realName, u.role,
               u.dept_id as deptId, u.class_id as classId,
               d.dept_name as department, 
               c.class_name as className
        from `user` u
        left join department d on u.dept_id = d.id
        left join sys_class c on u.class_id = c.id
    </sql>

    <select id="findByUsername" resultType="com.students.jwsystem_public.entity.User">
        <include refid="selectUserSql"/> where u.username = #{username}
    </select>

    <select id="findAll" resultType="com.students.jwsystem_public.entity.User">
        <include refid="selectUserSql"/> order by u.id
    </select>

    <select id="findAllTeachers" resultType="com.students.jwsystem_public.entity.User">
        <include refid="selectUserSql"/> where u.role = 'TEACHER'
    </select>

    <insert id="insertUser">
        insert into `user` (username, password, real_name, role, dept_id, class_id)
        values (#{username}, #{password}, #{realName}, #{role}, #{deptId}, #{classId})
    </insert>

    <update id="resetPassword">
        update `user` set password = #{password} where id = #{id}
    </update>

    <delete id="deleteById">
        delete from `user` where id = #{id}
    </delete>

    <select id="countByRole" resultType="java.lang.Integer">
        select count(*) from `user` where role = #{role}
    </select>
</mapper>
