        list.innerHTML = depts.map(d => `<div class="item-card">${d.deptName}</div>`).join('');
    }

    // --- 专业逻辑 ---
    async function initMajorTab() {
        const depts = await request('/admin/depts');
        const select = document.getElementById('selectDeptForMajor');
        select.innerHTML = '<option value="">请选择院系...</option>' + depts.map(d => `<option value="${d.id}">${d.deptName}</option>`).join('');
        document.getElementById('majorList').innerHTML = '<div style="color:#999;">请先选择上方院系</div>';
    }
    async function loadMajors() {
        const deptId = document.getElementById('selectDeptForMajor').value;
        if(!deptId) return;
        const majors = await request('/admin/majors?deptId=' + deptId);
        const list = document.getElementById('majorList');
        list.innerHTML = majors.map(m => `<div class="item-card">${m.majorName}</div>`).join('');
    }

    // --- 班级逻辑 ---
    async function initClassTab() {
        const depts = await request('/admin/depts');
        const select = document.getElementById('selectMajorForClass');
        let allMajors = [];
        for(let d of depts) {
            const ms = await request('/admin/majors?deptId=' + d.id);
            allMajors = allMajors.concat(ms);
        }
        select.innerHTML = '<option value="">请选择专业...</option>' + allMajors.map(m => `<option value="${m.id}">${m.majorName}</option>`).join('');
        document.getElementById('classList').innerHTML = '<div style="color:#999;">请先选择上方专业</div>';
    }
    async function loadClasses() {
        const majorId = document.getElementById('selectMajorForClass').value;
        if(!majorId) return;
        const classes = await request('/admin/classes?majorId=' + majorId);
        const list = document.getElementById('classList');
        list.innerHTML = classes.map(c => `<div class="item-card">${c.className}</div>`).join('');
    }

    // 通用弹窗
    async function openModal(type) {
        let html = '';
        if(type === 'dept') {
            html = `<h3>新增院系</h3>
                    <div class="form-group"><label>院系名称</label><input type="text" id="m-name"></div>
                    <div class="modal-actions"><button class="btn-cancel" onclick="closeModal()">取消</button><button class="btn-add" onclick="submitData('dept')">确认</button></div>`;
        } else if (type === 'major') {
            const deptId = document.getElementById('selectDeptForMajor').value;
            if(!deptId) return alert('请先选择院系');
            html = `<h3>新增专业</h3>
                    <div class="form-group"><label>专业名称</label><input type="text" id="m-name"></div>
                    <div class="modal-actions"><button class="btn-cancel" onclick="closeModal()">取消</button><button class="btn-add" onclick="submitData('major', ${deptId})">确认</button></div>`;
        } else {
            const majorId = document.getElementById('selectMajorForClass').value;
            if(!majorId) return alert('请先选择专业');
            html = `<h3>新增班级</h3>
                    <div class="form-group"><label>班级名称</label><input type="text" id="m-name"></div>
                    <div class="modal-actions"><button class="btn-cancel" onclick="closeModal()">取消</button><button class="btn-add" onclick="submitData('class', ${majorId})">确认</button></div>`;
        }
        document.getElementById('modalContent').innerHTML = html;
        document.getElementById('addModal').style.display = 'flex';
    }

    function closeModal() { document.getElementById('addModal').style.display = 'none'; }

    async function submitData(type, parentId) {
        const name = document.getElementById('m-name').value.trim();
        if(!name) return alert('请填写名称');

        let url = '', body = {};
        if(type === 'dept') { url = '/admin/add-dept'; body = { deptName: name }; }
        if(type === 'major') { url = '/admin/add-major'; body = { majorName: name, deptId: parentId }; }
        if(type === 'class') { url = '/admin/add-class'; body = { className: name, majorId: parentId }; }

        const data = await request(url, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body) });
        alert(data.message);
        if(data.success) {
            closeModal();
            if(type === 'dept') loadDepts();
            if(type === 'major') loadMajors();
            if(type === 'class') loadClasses();
        }
    }

    loadDepts();
</script>
</body>
</html>
