        where dept_id = #{deptId} and role = 'TEACHER'
        order by id
    </select>
```

**3. `AdminController.java` 加接口：**
```java
    @GetMapping("/teachers/by-dept")
    public List<User> getTeachersByDept(@RequestParam Long deptId) {
        return userMapper.findTeachersByDeptId(deptId);
    }
