### 📄 1. 覆盖 `CourseSelectionMapper.xml`
打开这个文件，把 `selectAllStudentsByTeacherId` 和 `selectStudentsByCourseId` 对应的 SQL 换成联表查询 `sys_class`：

```xml
<?xml version="1.0" encoding="UTF-8" ?>
<!DOCTYPE mapper PUBLIC "-//mybatis.org//DTD Mapper 3.0//EN" "http://mybatis.org/dtd/mybatis-3-mapper.dtd" >

<mapper namespace="com.students.jwsystem_public.mapper.CourseSelectionMapper">
    <!-- 其他语句保持不变 -->

    <!-- ✅ 修复1：教师端查询所有学生（联表查出班级名） -->
    <select id="selectAllStudentsByTeacherId" resultType="com.students.jwsystem_public.entity.CourseSelection">
        select distinct
        u.id             as studentId,
        u.username       as studentUsername,
        u.real_name      as studentName,
        sc.class_name    as className
        from course_selection cs
        inner join course c on cs.course_id = c.id
        inner join `user` u on cs.student_id = u.id
        left join sys_class sc on u.class_id = sc.id
        where c.teacher_id = #{teacherId}
        order by u.username
    </select>

    <!-- ✅ 修复2：教师端查询某门课的学生名单 -->
    <select id="selectStudentsByCourseId" resultType="com.students.jwsystem_public.entity.CourseSelection">
        select
        cs.id,
        cs.student_id    as studentId,
        cs.course_id     as courseId,
        cs.select_time   as selectTime,
        u.username       as studentUsername,
        u.real_name      as studentName,
        sc.class_name    as className,
        s.score          as score
        from course_selection cs
        inner join `user` u on cs.student_id = u.id
        left join score s on s.student_id = cs.student_id and s.course_id = cs.course_id
        left join sys_class sc on u.class_id = sc.id
        where cs.course_id = #{courseId}
        order by u.username
    </select>
</mapper>
```
*(注意：保留你 XML 里原有的 `insertSelection`、`deleteSelection` 等其他 SQL，只替换这两个 `<select>` 即可)*

