```java
    // ✅ 新增：将某个学生从【当前这门课】中移出
    @PostMapping("/remove-student-from-course")
    @Transactional
    public Map<String, Object> removeStudentFromCourse(@RequestBody Map<String, String> params) {
        Map<String, Object> result = new HashMap<>();
        try {
            Long studentId = Long.valueOf(params.get("studentId"));
            Long courseId = Long.valueOf(params.get("courseId"));

            // 1. 删成绩
            scoreMapper.deleteByStudentAndCourse(studentId, courseId);

            // 2. 删选课记录（如果有记录，说明确实选了，人数需要减一）
            int rows = courseSelectionMapper.deleteSelection(studentId, courseId);
            if (rows > 0) {
                courseSelectionMapper.decrementSelectedCount(courseId);
            }

            result.put("success", true);
            result.put("message", "已成功将该学生移出本课程");
        } catch (Exception e) {
            result.put("success", false);
            result.put("message", "操作失败: " + e.getMessage());
        }
        return result;
    }
