```java
package com.students.jwsystem_public.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.concurrent.TimeUnit;

@RestController
@RequestMapping("/test/redis")
public class RedisTestController {

    @Autowired
    private RedisTemplate<String, Object> redisTemplate;

    // 1. 测试 String（存字符串、验证码）
    @GetMapping("/string")
    public String testString() {
        // 相当于 SET student:name "张三"
        redisTemplate.opsForValue().set("student:name", "张三");
        // 相当于 GET student:name
        Object name = redisTemplate.opsForValue().get("student:name");

        // 存验证码，60秒过期
        redisTemplate.opsForValue().set("sms:code", "8888", 60, TimeUnit.SECONDS);

        return "String测试成功，取出的值是：" + name;
    }

    // 2. 测试 Hash（存对象）
    @GetMapping("/hash")
    public String testHash() {
        String key = "student:20240001";
        // 相当于 HSET / HMSET
        redisTemplate.opsForHash().put(key, "name", "陈娜涛");
        redisTemplate.opsForHash().put(key, "age", 20);
        redisTemplate.opsForHash().put(key, "class", "软件工程2101班");

        // 相当于 HGETALL
        Object name = redisTemplate.opsForHash().get(key, "name");
        return "Hash测试成功，取出的姓名是：" + name;
    }

    // 3. 测试 List（队列）
    @GetMapping("/list")
    public String testList() {
        String key = "course:queue";
        // 相当于 LPUSH
        redisTemplate.opsForList().leftPush(key, "student_A");
        redisTemplate.opsForList().leftPush(key, "student_B");

        // 相当于 RPOP
        Object popped = redisTemplate.opsForList().rightPop(key);
        return "List测试成功，出队的学生是：" + popped;
    }

    // 4. 测试 Set（去重）
    @GetMapping("/set")
    public String testSet() {
        String key = "course:tags";
        // 相当于 SADD（注意，存两次 Java，自动去重）
        redisTemplate.opsForSet().add(key, "Java", "MySQL", "Java");

        // 相当于 SMEMBERS，获取集合大小
        Long size = redisTemplate.opsForSet().size(key);
        return "Set测试成功，去重后的集合大小是：" + size + "（应该是2）";
    }

    // 5. 测试 ZSet（排行榜）
    @GetMapping("/zset")
    public String testZSet() {
        String key = "exam:math";
        // 相当于 ZADD
        redisTemplate.opsForZSet().add(key, "Zhang", 85);
        redisTemplate.opsForZSet().add(key, "Li", 95);
        redisTemplate.opsForZSet().add(key, "Wang", 78);

        // 相当于 ZREVRANGE（获取第一名）
        Object top = redisTemplate.opsForZSet().reverseRange(key, 0, 0);
        return "ZSet测试成功，第一名是：" + top;
    }
}
```

